h=19; w=16
G=[[4]*w for _ in range(h)]
orig={1:[(2,2),(4,14),(10,10),(17,9)],6:[(4,4),(6,6),(7,14),(15,2)]}
for col,pts in orig.items():
 for r,c in pts:G[r][c]=col
# Connect diagonally aligned same-color points; any foreign marker on that segment emits its color's full perpendicular diagonal.
for col,pts in orig.items():
 for i,(r1,c1) in enumerate(pts):
  for r2,c2 in pts[i+1:]:
   if abs(r2-r1)==abs(c2-c1) and r1!=r2:
    dr=1 if r2>r1 else -1; dc=1 if c2>c1 else -1
    for k in range(abs(r2-r1)+1):
     r,c=r1+dr*k,c1+dc*k
     if G[r][c]==4:G[r][c]=col
     elif G[r][c]!=col:
      other=G[r][c]
      # diagonal perpendicular to connector, full in bounds
      s=1 if dr==dc else -1 # connector slope sign; perpendicular sign opposite
      # line perpendicular has slope -s, so r+c const if s=1 else r-c const
      for rr in range(h):
       cc=(r+c)-rr if s==1 else rr+(c-r)
       if 0<=cc<w and G[rr][cc]==4:G[rr][cc]=other
print('\n'.join(' '.join(map(str,row)) for row in G))

G=[[4]*16 for _ in range(19)]
ones=[(2,2),(4,14),(10,10),(17,9)]; sixes=[(4,4),(6,6),(7,14),(15,2)]
for r,c in ones:G[r][c]=1
for r,c in sixes:G[r][c]=6
# connect only aligned 1 markers
for i,(r1,c1) in enumerate(ones):
 for r2,c2 in ones[i+1:]:
  if r1!=r2 and abs(r2-r1)==abs(c2-c1):
   dr=1 if r2>r1 else -1; dc=1 if c2>c1 else -1
   for k in range(abs(r2-r1)+1):
    r,c=r1+dr*k,c1+dc*k
    if G[r][c]==4:G[r][c]=1
    elif G[r][c]==6:
     # draw 6 line perpendicular, slope inverse to connector
     for rr in range(19):
      cc=(r+c)-rr if dr==dc else rr+(c-r)
      if 0<=cc<16 and G[rr][cc]==4:G[rr][cc]=6
print('\n'.join(' '.join(map(str,row)) for row in G))
